/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/sr.json — nu edita de mână */
__hubApps("sr",{"FreeDetect":{"line":"Желите да проверите да ли текст изгледа као да га је написала или копирала вештачка интелигенција? 42 спољна алата и генератор цитата на једном месту. Сама апликација ништа не открива.","detail":"Табла са 42 спољна алата за откривање вештачке интелигенције и плагијата и генератор цитата (проверава ISBN). Локално ништа не открива; помаже при провери референци.","tags":["каталог","цитати"]},"Arhiva-fara-frontiere":{"line":"Прегледајте збирке Internet Archive без налога: претрага, странице ставки, преглед и омиљене. Незванично; archive.org види вашу IP адресу и претраге.","detail":"Незванични прегледач збирки Internet Archive-а (претрага, странице ставки, преглед, омиљене ставке и недавне претраге сачуване локално), без налога. Не претражује Wayback Machine; archive.org добија вашу IP адресу и претраге.","tags":["веб архиве","извори"]},"AcademiSearch":{"line":"Једна претрага — научни чланци из десетина отворених извора. Списак можете сачувати за цитирање. Потребан је интернет; претраге иду овим сервисима.","detail":"Академска мета-претрага преко 11 отворених API-ја (OpenAlex, Crossref, arXiv итд.) плус везе ка порталима; извоз у BibTeX/RIS/CSV. Захтева интернет; ваши упити иду тим сервисима.","tags":["литература","извори"]},"Surveyor":{"line":"Које везе постоје на вашем сајту и које од њих не раде? Набраја их са сидрима и преусмеравањима. Спољне се не могу поуздано проверити. Само за ваше сопствене сајтове.","detail":"Прави попис веза на сајту (статички HTML, енглески интерфејс), укључујући сидра и преусмеравања. Спољне везе се не могу потврдити из прегледача (CORS); шаље захтеве; проверавајте само своје сајтове.","tags":["мртве везе","ревизија"]},"Trade-Free-Link-Guardian":{"line":"За ваш WordPress сајт: проналази покварене везе и поправља их без спољних сервиса. Мења стварни садржај, зато прво направите резервну копију. Није тестирано на правом WordPress-у.","detail":"WordPress додатак који проверава везе и детерминистички поправља покварене, без спољног сервиса. Мења стварни садржај: направите резервну копију. Није тестиран на правом WordPress-у.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Пратите своје сајтове и видите да ли одговарају. Ради само док је картица отворена. Страница са грешком се такође рачуна као одговор. Интерфејс је на енглеском.","detail":"Монитор доступности у прегледачу: проверава да ли ваши сајтови одговарају (не чита HTTP статусни код; 404/500 се рачунају као одговор). Само док је картица отворена. Енглески интерфејс.","tags":["праћење"]},"ScryVeil":{"line":"Проверите безбедност домена и добијте текстуални извештај који можете сачувати. Неке провере могу бити непотпуне или захтевати кључ. Повезује се са сервисима трећих страна; само за ваше домене.","detail":"Безбедносна дијагностика домена (DNS, RDAP, сертификати), са извозивим текстуалним извештајем; провере заглавља и репутације су често блокиране или захтевају кључ. Контактира треће стране; само за домене које поседујете.","tags":["OSINT","безбедност"]},"Vitrina":{"line":"Убаците јавну Facebook објаву на свој сајт без налога и копирајте готов код. Незванично; Meta види вашу IP адресу, приказивање није загарантовано.","detail":"Уграђује јавне Facebook странице/објаве преко Meta додатака, незванично; копира код за уградњу. „Без налога“ не значи „без праћења“: Meta види вашу IP адресу; приказ није загарантован.","tags":["праћење извора"]},"Threads-fara-cont":{"line":"Читајте јавне Threads објаве без налога и сачувајте их као текст. Незванично; Meta види вашу IP адресу, понекад је потребан посредник.","detail":"Приказује јавне Threads објаве преко Meta уградње, без налога; опционо локално чување, извоз у .txt. Meta види вашу IP адресу; може бити потребан CORS прокси. Незванично.","tags":["праћење извора"]},"X-fara-cont":{"line":"Приступите јавним профилима и објавама на X без налога на неколико начина: директна веза, архива, претрага или Nitter. Не чита садржај; шаље везу на archive.org.","detail":"Прави путање приступа јавним X профилима и објавама без налога: директна веза, Wayback архива, претрага, Nitter. Не чита садржај; шаље корисничко име/везу сервису archive.org.","tags":["праћење извора"]},"Arhiva-LinkedIn":{"line":"Чувајте на једном месту белешке о LinkedIn објавама које сте сами налепили и извезите их као текст. Галерија користи званично уграђивање, па се повезује са LinkedIn-ом. Незванично.","detail":"Архива белешки о ручно налепљеним LinkedIn објавама (увоз CSV, извоз Markdown) + галерија преко званичне LinkedIn уградње (контактира LinkedIn). Незванично.","tags":["архивирање"]},"Cadraj":{"line":"Сакупљајте TikTok клипове ручно, груписане по ауторима, и гледајте их у званичном плејеру. Можете означити оне које сте већ гледали.","detail":"Ручна колекција TikTok клипова по аутору, који се пуштају преко званичног плејера; ознака „виђено“.","tags":["праћење извора"]},"FASCICUL":{"line":"Претвара телефоне у просторији у заједничку таблу на видео пројектору: цртежи, белешке, слике, ласерски показивач и камера уживо. Тестирано на рачунару; на правим телефонима још није потврђено.","detail":"Телефони ↔ видео пројектор: заједничка табла са цртањем, белешкама, сликама, ласерским показивачем и камером уживо, у једној датотеци. Директна WebRTC веза у локалној мрежи, без сервера треће стране; опционални релеј на телефону који држи хотспот (Android/Termux). Тестирано у Chromium-у; још није проверено на стварним телефонима.","tags":["сарадња"]},"INDICATIV":{"line":"Припремите радио-аматерски испит ANCOM без интернета: 723 питања са размакнутим понављањем. Незванично; банка питања је проверена само делимично.","detail":"Незванични тренер за испит за радио-аматере ANCOM, ради без интернета (723 питања, понављање у размацима, претрага банке питања). Није ANCOM материјал; банка питања је само делимично проверена.","tags":["испит","радио"]},"ETER":{"line":"Научите радио-аматеризам у енциклопедији: Морзеова азбука, вежбач, калкулатори антена и претрага по целом садржају.","detail":"Енциклопедија радио-аматеризма: Морзеова азбука, Кохов тренер, калкулатори антена, глобална претрага.","tags":["радио","енциклопедија"]},"ATINGERE":{"line":"Претвара књигу у Брајево писмо са вибрацијама на екрану осетљивом на додир за глувослепе или у аудио-књигу за слепе. Није проверено са читаоцима Брајевог писма; има ограничења.","detail":"Претвара књиге у тактилни брајев запис или аудио-књиге. Није проверено са изворним читаоцима; погледајте ограничења у README-у.","tags":["приступачност"]},"Clopotel":{"line":"Стигните на време на конференцији или радионици: сценски тајмер са вашим програмом и сигнал када се крај приближава. На румунском и енглеском.","detail":"Тајмер за сцену са програмом говорника (увоз текста/CSV) и сигналом упозорења, RO/EN.","tags":["догађаји","MIT"]},"Monstrarium":{"line":"Испланирајте радионицу прављења чудовишта од рециклираног материјала: апликација рачуна материјал и сесије, нуди 50 чудовишта са звуком, 3D и образовном игром.","detail":"Планер радионице чудовишта од рециклираног материјала: сам израчунава материјале, распоред по серијама, 50 оригиналних чудовишта са звуковима, 3D и образовна игра.","tags":["радионица","MIT"]},"TranslateHub":{"line":"Бирајте међу 22 алата за превођење или преводите уз ВИ помоћу сопственог кључа. Текст преведен ВИ-ом одлази Anthropic сервису.","detail":"Именик од 22 алата за превођење плус AI преводилац уз ваш сопствени кључ. AI текст се шаље на api.anthropic.com.","tags":["превод","ВИ"]},"DataWeave":{"line":"Отворите табелу и схватите је: статистика, графикони, пивот табеле и корелације. Ваши подаци остају на вашем уређају.","detail":"Истражујте CSV/TSV/JSON у једној датотеци: табела, статистика, графикони, пивот табела и корелације; ваши подаци остају на вашем уређају.","tags":["подаци"]},"MarkdownAtelier":{"line":"Пишите документе у Markdown-у и одмах видите како изгледају, са једноставним формулама; на 7 језика, без интернета. Текстови остају у вашем прегледачу; чувајте резервну копију.","detail":"Markdown уређивач без интернета са прегледом, GFM, подскупом LaTeX-а (MathML), 7 језика, претрагом и резервном копијом у .json. Документи остају у прегледачу.","tags":["писање"]},"RegexLab":{"line":"Испробајте регуларни израз и одмах видите шта хвата; објашњења корак по корак, тестови и упозорење ако може да замрзне програм.","detail":"Тестирање регуларних израза у JavaScript-у са објашњењима, тестовима и упозорењем на ReDoS.","tags":["развој"]},"SEOptimum":{"line":"Проверите колико је веб страница спремна за претраживаче. 20 алата, укључујући анализу странице и преглед њеног изгледа у резултатима претраге.","detail":"20 SEO алата у прегледачу: анализа странице, прегледи SERP-а.","tags":["веб"]},"SEVA":{"line":"Сазнајте о сну, дневном ритму тела, дисању и исхрани у енциклопедији коју можете и да саслушате. Само информативно; није медицински савет.","detail":"Енциклопедија благостања: сан, циркадијални ритам, дисање, исхрана; слушање уз гласно читање. Информативно; није медицински савет.","tags":["здравље"]},"PULS":{"line":"Шта радити док хитна не стигне? Румунски водич за прву помоћ са метрономом за КПР и необавезном картицом за хитне случајеве. Клинички непроверено; позовите 112.","detail":"Водич за прву помоћ на румунском (КПР уз метроном, подвеза), са претрагом и опционалном картицом за хитне случајеве. Садржај није клинички потврдио стручњак; не замењује овлашћени курс. У хитном случају позовите 112.","tags":["здравље","хитни случајеви"]},"VATRA":{"line":"Шта радити ако у природи остане без воде, ватре или склоништа? Енциклопедија преживљавања без интернета, са претрагом и белешкама. Само у едукативне сврхе; у хитном случају позовите 112.","detail":"Енциклопедија преживљавања без интернета (вода, ватра, склониште, оријентација), са претрагом и локално сачуваним белешкама. Образовни материјал, не замењује курс прве помоћи; у хитном случају позовите 112.","tags":["рад на терену"]},"Eclipsa-2027":{"line":"Погледајте на мапи без интернета где и колико траје потпуно помрачење Сунца 2. августа 2027, са градовима и претрагом места. Вредности су оријентационе; не гледајте у Сунце без филтера.","detail":"Мапа потпуног помрачења од 2. августа 2027. без интернета, са трајањима, покривеношћу по градовима и претрагом места. Оријентационе вредности; не гледајте у Сунце без сертификованих филтера.","tags":["астрономија"]},"orarium":{"line":"Колико је сати сада на Марсу, на Месецу или на астероиду? Локално време уживо на 45 небеских тела. Приближан модел, интернет није потребан; није за навигацију.","detail":"Време на сваком свету: локално време уживо на 45 тела (Месец, Марс, планете, месеци, астероиди), брзина часовника у односу на Земљу, удаљеност и време повратног пута сигнала, конвертор временских зона и мапе колонизације. Оријентациони модел, без интернета; није за навигацију. Укључује поноћ и подне на сваком телу, прозоре преноса Земља–тело и везу ка TerRa.","tags":["астрономија","време"]},"TerRa":{"line":"3D глобус и мапа који приказују дан и ноћ на Земљи, Месецу и планетама. Положаји сателита могу каснити око 3 месеца док их не освежите онлајн.","detail":"3D глобус и мапа: терминатор, Месец, планете. Сателити користе застарели снимак (~3 месеца) без интернета; за тренутне положаје освежите онлајн. Јединствена веза за сваки приказ; небо са било ког од 45 тела ORARIUM-а, повезано у оба смера.","tags":["астрономија"]},"Horizons.BeyondLimits":{"line":"Путујте кроз историју Свемира од Великог праска до краја кроз 91 прекретницу. Будућност је научна спекулација, а не тачно предвиђање.","detail":"Временска мапа од Великог праска до краја свемира: 91 догађај, извоз у Markdown; будућност је спекулативна, није потврђено предвиђање.","tags":["космологија"]},"Hyper4D":{"line":"Погледајте како изгледају четвородимензионални облици: окрећите их на екрану и посматрајте из неколико углова. Слике се могу сачувати.","detail":"4D геометрија у SVG-у: 3D пресеци 4D тела и политопа са 4D→3D→2D пројекцијама које се ротирају у реалном времену, извоз у SVG.","tags":["математика"]},"ExploratoriiEco":{"line":"Теренски водич за љубитеље природе: од класификације живих бића и трагова до биома Румуније, дневник посматрања, етика и хитни случајеви.","detail":"Теренски водич за природњаке у 20 одељака: класификација живота, трагови и знаци, румунски биоми, калкулатори, дневник, етика, хитни случајеви и речник.","tags":["природа"]},"FieldObserver":{"line":"Бележите своја теренска посматрања; очитавања сензора телефона додају се аутоматски. Водите архиву својих изласка.","detail":"Дневник теренских осматрања уз сензоре телефона; архива, извоз у JSON/CSV.","tags":["рад на терену"]},"VietAR":{"line":"Фотографишите или снимите биљку или створење и добијте представу међу 519 врста из Румуније. Може погрешити; не једите ништа на основу тога.","detail":"Оријентационо препознавање 519 румунских врста по слици/звуку; може бити погрешно, не једите биљке или печурке на основу њега. Модели се преузимају од трећих страна; не ради потпуно без интернета.","tags":["биодиверзитет"]},"VOIAJOR":{"line":"Пратите путање Војаџера 1 и 2 од 1977. до милијарду година унапред, у свакој размери — од планета до Млечног пута. Оријентациони модел, није за навигацију.","detail":"Симулација путања Voyager 1 и 2 (1977. до преко милијарду година): балистички лукови између стварних прелета, екстраполација уз Сунчеву гравитацију и локалну галактичку динамику, хелиосфера, Оортов облак и 19 оближњих звезда са сопственим кретањем.","tags":["Војаџер","симулација"]},"Nemurirea":{"line":"Откријте како тело стари и шта наука каже о биолошким сатовима и дугом животу, па се проверите тестом. Није медицински савет.","detail":"Интерактивни есеј о биолошким сатовима и науци о дуговечности, са завршним квизом. Информативне намене, није медицински савет.","tags":["биологија"]},"IncredibleCosmos":{"line":"Распоредите планете и звезде тако да њихова гравитација усмери комету ка циљу. 108 нивоа, три тежине и до три звездице по нивоу.","detail":"Гравитациона слагалица: поставите планете и звезде тако да њихова гравитација усмери комету ка циљу; 108 нивоа у 12 категорија, три тежине, оцена 1–3 звездице, са претрагом.","tags":["игра","физика"]},"Cupa-Mondiala-2026":{"line":"Играјте на Светском првенству 2026 и пратите развој замишљеног турнира. Резултати су насумични, нису прогноза; незванично.","detail":"Измишљени, незванични симулатор Светског првенства 2026: насумични резултати, не предвиђања; није повезан са FIFA.","tags":["симулација","незванично"]},"AGORA":{"line":"Како је настао евро и шта значи за Румунију? 59 поглавља од Мастрихта до ЕЦБ, плус савети за путнике. Незванично.","detail":"Информативни атлас еврозоне у 59 одељака: од Мастрихта и ЕЦБ до Румуније и евра, плус водич за путнике. Незванично, без правне вредности.","tags":["економија","ЕУ"]},"URME":{"line":"Припремите се за планинарење стазом Колци–Алуниш у Бузауу: биљке, ћилибар, фосили, време изласка и заласка сунца, опрема. Мапа није за навигацију.","detail":"Информативни, незванични планинарски водич за Colți–Aluniș (биљке, ћилибар, фосили), са изласком/заласком сунца и списком опреме. Схематска мапа, није за навигацију; вађење из заштићеног подручја је забрањено.","tags":["природа","Бузау"]},"Belot-fara-frontiere":{"line":"Упознајте белот и сродне игре у другим земљама, па играјте за столом: ви и ВИ партнер против два ВИ противника. Блок за бодове је укључен.","detail":"Атлас породице игара белот/бела/klaverjas/jass и игра за 4 играча (ви и AI партнер против два AI противника); румунски белот има приоритет; листа за бодовање.","tags":["карте","ВИ"]},"Scopone-fara-frontiere":{"line":"Сазнајте како је настао скопоне, која су му правила и како се она мењају од региона до региона, па играјте против рачунара који уме да даје савете.","detail":"Атлас игре scopone (15 листова: порекло, правила, регионалне разлике) и игра против локалног AI-ја (хеуристика / Monte-Carlo), са саветима; италијанске или француске боје.","tags":["карте","ВИ"]},"Solitaire-fara-frontiere":{"line":"Прегледајте и играјте пасијансе као што су Klondike, FreeCell или Spider. Када заглавите, затражите савет или пустите рачунар да реши.","detail":"Атлас пасијанса (Klondike, FreeCell, Spider и други) на заједничком мотору; „Савет“ од решавача са ограничењем чворова/времена и опционално аутоматско решавање.","tags":["карте"]},"Sudoku-fara-frontiere":{"line":"136 врста судокуа — од класичног до killer и 3D; прегледајте и играјте. Помаже објашњењима корак по корак и решава ваше сопствене загонетке.","detail":"Атлас од 136 варијанти судокуа (класични, killer, jigsaw, грчко-латински, 3D и многе друге), са генератором јединственог решења, решавањем корак по корак уз објашњења, 7 начина игре и решавачем.","tags":["загонетке"]},"Domino-fara-frontiere":{"line":"Научите историју и правила домина, па играјте за столом против једног до три противника које води рачунар. Потез се може поништити.","detail":"Атлас домина (порекло, правила, апроксимације) и сто за игру против 1–3 AI играча, са три нивоа; поништавање потеза.","tags":["домине","ВИ"]},"Mahjong-fara-frontiere":{"line":"Упознајте 8 врста маџонга; играјте пасијанс или игру у четворо са три једноставна противника које води рачунар. Ради без интернета.","detail":"Атлас 8 варијанти мајонга, пасијанс и мајонг за 4 играча (riichi, Хонг Конг, Сечуан) против 3 једноставна хеуристичка AI-ја. Без интернета.","tags":["маџонг","ВИ"]},"Go-fara-frontiere":{"line":"Сазнајте одакле долази го и како се игра, па окушајте се против рачунара који уме да даје савете. Не шаље никакве податке преко интернета.","detail":"Атлас игре го (18 листова: порекло, правила, апроксимације) и игра против локалног AI-ја (Monte-Carlo, није LLM), са SGF-ом и саветима; без мрежних захтева.","tags":["го","ВИ"]},"Zaruri-fara-frontiere":{"line":"26 игара са коцкама о којима можете читати, 12 против рачунара; плус симулатор бацања са вероватноћама. Без новца; ван мреже.","detail":"Атлас 26 игара са коцкицама; 12 се може играти против дидактичког AI-ја (није LLM), плус NdM симулатор са тачним вероватноћама. Није игра на срећу; без интернета.","tags":["коцке"]},"Sah-fara-frontiere":{"line":"Више од 700 варијанти шаха за истраживање и мали речник појмова; већину можете играти против рачунара. Ради без интернета.","detail":"706 јединица варијанти шаха (само за неке постоји проверен извор; неке су синтетичке) и 299 појмова лексикона. Без интернета, са локалним мотором за многе варијанте.","tags":["шах"]},"Dame-fara-frontiere":{"line":"Играјте 25 варијанти даме против рачунара и сачувајте партију. Правила 16 од њих су само приближна и означена су знаком ⚠.","detail":"25 варијанти даме које се могу играти против дидактичког AI-ја, са извозом партије; 16 има приближна правила (означено ⚠).","tags":["дама"]},"Table-fara-frontiere":{"line":"Табла, тавли, нарди и румунске варијанте табле; читајте и играјте: 17 варијанти против рачунара, тастатуром или мишем.","detail":"Атлас породице игре табле (backgammon) који се може играти: backgammon, Tavli, Tavla, Narde, Gul Bara и румунске варијанте; 17 варијанти против AI-ја за учење; игра тастатуром.","tags":["табла"]},"Remi-fara-frontiere":{"line":"Упознајте породицу ремија и играјте 19 варијанти против рачунара са статистиком. 8 језика; крупне, лако видљиве плочице или карте.","detail":"Атлас породице игара ремија: 19 варијанти које се могу играти против локалног AI-ја, са статистиком; интерфејс на 8 језика, са великим плочицама и картама.","tags":["реми"]},"Carti-de-joc-fara-frontiere":{"line":"Од пасијанса и «Будале» до покера: 17 игара са картама са објашњеним правилима, 8 њих можете одмах играти.","detail":"Интерактивни атлас игара са картама, од пасијанса и Црног Пере до покера: 17 игара са листовима правила, од којих се 8 може играти.","tags":["карте"]},"Undava":{"line":"Припремите квиз или га играјте са пријатељима на истом телефону или рачунару и поново играјте питања на која сте погрешно одговорили. Слично Kahoot-у, али без повезивања.","detail":"Квиз у стилу Kahoot-а (није повезан са њим), у једној датотеци: соло или наизменично на истом уређају, са понављањем грешака. Игра уживо постоји само у серверском издању.","tags":["квиз","образовање"]},"AI-Liber":{"line":"Разговарајте са неколико ВИ асистената на једном месту, неки раде на вашем рачунару. Поруке иду провајдеру кога изаберете; ВИ може да погреши.","detail":"Ћаскање са више AI провајдера, укључујући локалне (Ollama, WebLLM). Поруке иду провајдеру кога изаберете; AI одговори могу бити погрешни.","tags":["ВИ"]},"LocalMind":{"line":"Ћаскајте са малим ВИ асистентом који ради директно у вашем прегледачу. Модели се преузимају са интернета једном; може да погреши.","detail":"Ћаскање са малим моделима (Qwen3, LFM2) који раде локално у прегледачу (WebGPU). Модели долазе са Hugging Face-а; може погрешити. Захтева локални сервер или јавну страницу.","tags":["локална ВИ"]},"PromptVault":{"line":"Више од 500 готових упита за ВИ асистенте; бирајте и означавајте омиљене. Не чува ваше сопствене текстове.","detail":"Библиотека од 500+ упутстава (промпти) са омиљеним, није менаџер за ваша сопствена упутства.","tags":["упити"]},"ARENA":{"line":"Натерајте два ВИ модела да одговарају на слепо и гласајте за бољи; рангирање се чува на вашем рачунару. Потребни су ваши сопствени кључеви.","detail":"Слепи дуели између AI модела са локалном Elo ранг-листом (извоз у CSV). Захтева ваше сопствене API кључеве или локалне сервере; демо модели су симулирани.","tags":["евалуација ВИ"]},"Nexus-fara-frontiere":{"line":"Ћаскајте са ВИ асистентима неколико провајдера; разговор са претрагом и чувањем. Потребни су интернет и ваши кључеви, који се чувају нешифровани.","detail":"Клијент за AI ћаскање који користи ваше сопствене API кључеве (Anthropic, OpenAI, Google, компатибилни са OpenAI), са претрагом и извозом у Markdown; „агенти“ су упутства. Захтева интернет; кључеви се чувају нешифровани.","tags":["агенти"]},"VoiceAtelier":{"line":"Саслушајте како звуче стотине вештачких гласова на десетинама језика и сазнајте како се прави аудио-књига. Онлајн узорак шаље текст спољним сервисима само уз вашу дозволу.","detail":"Каталог од 427 неуронских гласова (141 локалитет) и водич за аудио-књиге. Онлајн узорак шаље текст релеју и Microsoft-у, само уз вашу сагласност. Није TTS студио.","tags":["глас"]},"Trusa-fara-frontiere":{"line":"Скуп од 15 малих свакодневних алата: белешке, табела, Markdown, лозинке, финансијски дневник и још. Нема званичну везу са YunoHost-ом који је инспирисао категорије.","detail":"Скуп од 15 малих модула писаних од нуле (белешке, табела, Markdown, лозинке, финансијски дневник и више), инспирисаних категоријама апликација YunoHost-а; није повезан са њим.","tags":["алатке"]},"API-fara-frontiere":{"line":"Време, NASA снимци, положај ISS-а и десетине података уживо на једном месту. Потребан је интернет; није тестирано са правим сервисима.","detail":"52 виџета: 47 преко јавних API-ја (потребан интернет; при отварању онлајн аутоматски контактира Open-Meteo, NASA и ISS) и 5 локалних алата. Није тестирано са стварним серверима.","tags":["API"]},"OmniHost":{"line":"Велики пакет од преко сто радних алата на једном месту. Повезује се са четири спољна сервиса; детаљи су у README-у.","detail":"Пакет за продуктивност (~4 MB, 141 модул). Контактира четири спољна хоста; погледајте README.","tags":["пакет"]},"VNTV":{"line":"Пуштајте VideoNeat трејлере као телевизијски канал без прекида. Потребан је интернет; у P2P режиму ваша адреса је видљива другим гледаоцима.","detail":"VideoNeat трејлери као непрекидан ТВ програм, плус Stremio додатак. Захтева интернет (videoneat.com, videos.trom.tf); у P2P режиму ваша IP адреса је видљива другим гледаоцима.","tags":["медији","MIT"]},"OSATURA":{"line":"Оживите 2D цртеже: повежите их са «скелетом», покрените и извезите анимацију у неколико формата. Алфа верзија, до сада мало тестирана.","detail":"Мотор за 2D векторски ригинг и анимацију у Rust-у (кости, IK, скининг, физика, машине стања) са студијом у прегледачу и извозом у SVG, PNG, GIF, Lottie и glTF. Изворни програм (командна линија + студио) и WebAssembly модул, није једна HTML датотека; алфа, корисници га још мало користили. Лиценце: библиотеке MPL-2.0, CLI AGPL-3.0-or-later.","tags":["анимација","MPL/AGPL"]},"OAZA":{"line":"340 бесплатних веб сервиса, углавном без налога, у једном каталогу. Списак је проверен у јуну 2026, али не аутоматски.","detail":"Каталог од 340 бесплатних веб сервиса трећих страна, обично употребљивих без налога (није аутоматски проверавано; проверено јуна 2026).","tags":["сервиси"]},"VaultCrypt":{"line":"Имате нешто да сакријете од радозналих очију? Закључајте датотеке и текстове лозинком директно у прегледачу. Изгубљена лозинка се не може повратити.","detail":"AES-256-GCM шифровање датотека и текста у прегледачу. Није независно ревидирано; изгубљена лозинка се не може повратити.","tags":["безбедност"]},"Akasha":{"line":"Бележница која ради без интернета, са ознакама, претрагом и везама између страница. Да ништа не изгубите, преузимајте свежу копију датотеке.","detail":"Белешке без интернета у једној датотеци, са ознакама, претрагом и везама [[Наслов]]; да бисте сачували податке, преузимате свежу копију датотеке (quine).","tags":["белешке"]},"CLEPSIDRA":{"line":"Сат за одбројавање, аларм и распореди за радне дане и викенде. Прати празнике и ваше сопствене догађаје.","detail":"Обрнути сат, аларм, распореди за радне дане/викенд, празници, догађаји.","tags":["време"]},"Origami":{"line":"Научите да савијате папир корак по корак: ознаке, технике и илустровани модели. Апликација памти где сте стали.","detail":"Водич за оригами: ознаке, технике, модели корак по корак, са напретком сачуваним локално.","tags":["уметност"]},"Zicala":{"line":"Једна румунска пословица дневно из збирке од 550. Можете претраживати и чувати омиљене; коментари су написани уз помоћ ВИ.","detail":"550 румунских пословица са пословицом дана, претрагом и извозом/увозом омиљених; SWOT/TOWS коментари су уз помоћ AI-ја.","tags":["култура"]},"Limpezimea":{"line":"Читајте научнофантастични роман «Limpezimea» на седам језика. Пратећа хроника и критичка студија написане су уз помоћ ВИ (Claude).","detail":"СФ роман „Limpezimea“ на 7 језика, читалачко издање. Критички апарат (хроника, студија) написан је уз помоћ AI-ја (Claude).","tags":["књижевност"]},"Nota-Zero":{"line":"Спекулативна фантастична прича о теорији струна на румунском, енглеском и француском, са белешкама које објашњавају научне идеје. Измишљено је, није академски извор.","detail":"Спекулативна фантастична прича о теорији струна, на румунском, енглеском и француском, са објашњавајућим научним напоменама (фикција, није академски извор).","tags":["књижевност"]},"Pendulul":{"line":"Планета се њише између три звезде и црне рупе: научнофантастични роман у девет томова који је Alexio написао заједно са Claude-ом. 3D симулација, читач са чувањем за читање ван мреже, EPUB и PDF.","detail":"СФ роман у девет томова аутора Alexio, писан са Claude-ом: планета осцилује између три звезде и црне рупе. Укључује 3D симулацију и читач књиге у једној HTML датотеци коју можете сачувати и читати без интернета, плус EPUB и PDF.","tags":["књижевност"]},"PrintreInteligente":{"line":"Закорачите у интерактивни научнофантастични роман са ликовима инспирисаним посадом Артемиса 2. Прегледи су измишљени; превод, глас и ВИ функције користе спољне сервисе.","detail":"Интерактивни СФ роман, фикција са ликовима инспирисаним посадом Artemis 2; рецензије су измишљене. Превод, онлајн глас и AI функције користе спољне сервисе.","tags":["књижевност"]},"BorderlessMelodies":{"line":"Слушајте музику која сама себе компонује директно у прегледачу. Можете извести као аудио; постоји тајмер за спавање.","detail":"Процедурална музика у Web Audio-у, са извозом звука и тајмером за спавање.","tags":["музика"]},"EcoulSpectral":{"line":"Погледајте звук као слику, изаберите део који вам смета и одвојите га или избришите. Укључује смањење шума, откривање звукова и чување као WAV.","detail":"Локални уређивач спектрограма: означите област време–фреквенција и издвојите или уклоните; детекција гласа, смањење шума, извоз у WAV.","tags":["аудио"]},"Constelar":{"line":"Разговарајте са виртуелним пријатељима који памте ваше разговоре. По правилу одговарају по једноставним правилима; права ВИ само ако изаберете провајдера, и тада му иду ваше поруке. Само за одрасле.","detail":"Разговорни сапутници са локалном меморијом. Подразумевано једноставан мотор заснован на правилима; права AI само ако изаберете провајдера (поруке му се шаљу). За одрасле; не замењује терапију.","tags":["ВИ"]},"Tarot":{"line":"Истражите историју тароа, симболе карата и начин на који се читају као културни феномен. Интерактивни курс у вашем темпу.","detail":"Интерактивни курс: историја, симболи и тумачење карата, као културни феномен.","tags":["култура"]},"Numerologie":{"line":"Истражите нумерологију као симболичку традицију на четири нивоа, са вежбама, речником, дневником и калкулатором. Представљено без научне потврде.","detail":"Интерактивни курс о нумерологији као симболичкој традицији: четири нивоа, вежбе, речник, дневник и калкулатор; представљено без научне потврде.","tags":["култура"]},"PUNCTUM":{"line":"Образовни атлас акупресуре и терапија заснованих на тачкама: више од 400 тачака на интерактивним мапама, рутине самопомоћи са вођеним сесијама, докази и безбедност. Не замењује лекара.","detail":"Образовни атлас терапија заснованих на тачкама (акупунктура, акупресура, мокса, купинг, аурикуларна терапија, рефлексологија и више): 410 тачака на 14 меридијана, 60 варијанти са нивоом доказа, SVG мапе, стања и рутине, курс, квиз, картице за учење и личне безбедносне провере.","tags":["здравље","докази"]},"Reiki":{"line":"Сазнајте шта је реики, духовна пракса, и шта кажу истраживања: није нађено довољно доказа за дејство изнад опуштања. Не замењује лекара.","detail":"Курс о реикију, духовној пракси: прегледи налазе недовољно доказа о било каквом ефекту осим опуштања/плацеба; не замењује лекара.","tags":["култура"]},"Bioenergoterapie":{"line":"Курс који објашњава шта је биоенергетска терапија и одакле потиче. Нема научних доказа за лековито дејство праксе; не замењује лекара.","detail":"Курс о биоенергетској терапији, пракси без научних доказа о лечењу; не замењује лекара.","tags":["култура"]},"CHIROMANTIA":{"line":"Интерактивни атлас хиромантије: мапа длана са линијама, брежуљцима, прстима и типовима руку, читана као културна традиција; са одељком о науци и критичком мишљењу. Нема научне потврде.","detail":"Интерактивни атлас хиромантије: SVG мапа длана (лева/десна), линије, брегови, прсти, типови шаке, отисци прстију, 2D:4D мерења, вођено читање, картице за учење, квиз, Barnum слепи тест и симулатор cold-reading-а; свака тврдња има ниво доказа.","tags":["хиромантија","култура"]},"Radiestezie":{"line":"Прођите 18 нивоа о тражењу воде вилином метлицом, са речником, дневником праксе и међународним додацима. Од почетка наводи да нема научне потврде.","detail":"Курс у 18 нивоа о радиестезији, са речником, дневником праксе и међународним додацима; од почетка наводи да нема научну потврду.","tags":["култура"]},"Inforenergetica":{"line":"Сазнајте у структурираном курсу шта тврди инфоенергетика, нетрадиционална пракса. Нема научне потврде; није медицински савет.","detail":"Курс о инфоенергетици, неконвенционалној пракси без научне потврде; није медицински савет.","tags":["култура"]},"ECLIPSA":{"line":"Сазнајте у коју астролошку кућу ваше наталне карте пада помрачење и о наредних 12 помрачења. Прорачун је приближан, тумачење симболично; нема научне потврде.","detail":"У коју астролошку кућу пада помрачење на наталној карти, плус наредна 12 помрачења. Локални, приближни астрономски прорачун; симболичко тумачење, астрологија нема научну потврду.","tags":["астрологија"]},"Afrodisiace-fara-frontiere":{"line":"Читајте о 22 намирнице и биљке које се традиционално повезују са жељом, са нивоом доказа за сваку. Културни водич за одрасле, није медицински савет.","detail":"Културни водич кроз 22 намирнице и биљке традиционално повезане са жељом, са нивоом доказа за сваку ставку. Образовно, није медицински савет.","tags":["култура"]},"CalmWaves":{"line":"Амбијентална музика за опуштање и спавање, стварана у ходу. Није медицински уређај; одељак о истраживањима није независно проверен. Консултујте лекара (епилепсија).","detail":"Генеративна амбијентална музика за опуштање/спавање. Није медицински уређај; одељак са истраживањима није независно проверен. Затражите лекарски савет (епилепсија).","tags":["аудио"]},"ASMR":{"line":"Направите сопствени умирујући звучни пејзаж од слојева амбијента, звукова додира и бинауралних откуцаја. Има тајмер за спавање и можете поделити свој миx.","detail":"Миксер звукова за опуштање који се ствара у реалном времену (Web Audio): амбијентални слојеви, звуци додира, бинауралне фреквенције и тајмер за спавање; микс се може делити.","tags":["аудио"]},"NOMIA":{"line":"Какав би могао бити први контакт између људи, ВИ и других врста ума? 1001 измишљен сценарио; фикција, не стварност. Ради и ван мреже.","detail":"Концептуални симулатор протокола контакта Човек–AI–NHI, 1001 ставка, пратилац антологије „Printre inteligențe“. Фикција/спекулација, не проверене чињенице; PWA без интернета, RO/EN.","tags":["фикција","спекулација","PWA"]},"ValeaPlopului1972":{"line":"Погледајте НЛО догађај из 1972. споља, изнутра и у симулацији, реконструисан у 3D. То је замишљена хипотеза, а не доказ.","detail":"3D реконструкција случаја НЛО-а Valea Plopului (1972): спољашњост, симулација, замишљена унутрашњост. Спекулативно, засновано на непроверним јавним изворима, без сагласности именованих особа; није доказ.","tags":["НЛО","3D","фикција"]},"HoroScop":{"line":"Израчунајте положаје планета за датум и место, па истражите наталну карту, аспекте и компатибилност. Симболичка астрологија, без научне основе. Ради ван мреже.","detail":"Лична ефемерида без интернета: положаји планета се рачунају у прегледачу (смањена прецизност), натална карта, аспекти, синастрија. Симболичка астрологија, без научне потврде; лиценца MIT.","tags":["астрологија","ефемериде","ван мреже"]},"Aurora":{"line":"Слушајте умирујуће тонове и благо пулсирајуће звукове и пратите водич за дисање. Само за опуштање, није лечење. Ради без интернета.","detail":"Звучно уточиште: тонови чакри, бинауралне фреквенције и водич за дисање, без интернета. Само опуштање, није медицина; фреквенције немају научну потврду. Лиценца MIT; независан пројекат.","tags":["медитација","аудио","опуштање"]},"NumeroLogIA":{"line":"Сазнајте шта нумерологија, кинеска БаЦзи астрологија и биоритам кажу о вашем датуму рођења, уз објашњен сваки прорачун. Симболички систем, без научне основе.","detail":"Питагорејска/халдејска нумерологија, BaZi и биоритам на 7 језика, прорачуни корак по корак, портрети који се могу извести у JSON; опциони AI пророк преко вашег сопственог модела. Симболички систем, без научне потврде; лиценца MIT.","tags":["нумерологија","ВИ","ван мреже"]},"FrequencyLaboratory":{"line":"Испробавајте звукове, ефекте и тестове слуха у малој звучној лабораторији. «Терапијски» ефекти нису доказани; не замењује лекара. Ради ван мреже.","detail":"Аудио лабораторија у прегледачу (осцилатори, бинаурални, ефекти, анализатори, тестови слуха), без интернета. Само информативно: „терапијске“ поставке немају доказан медицински ефекат; није медицински уређај.","tags":["аудио","лабораторија","ван мреже"]},"generator-frecvente":{"line":"Стварајте чисте тонове и пулсирајуће парове, слушајте познате унапред подешене вредности и грубо проверите слух. Није медицински уређај. Ради ван мреже.","detail":"Генератор тонова у прегледачу (бинаурални, секвенцер, EQ, оријентациони тест слуха, претрага поставки), без интернета. Само информативно: Solfeggio/Schumann поставке немају научну потврду; није медицински уређај.","tags":["аудио","генератор","ван мреже"]},"ACORDAJ":{"line":"Прегледајте више од хиљаду духовних курсева и иницијација са историјским контекстом и критичким погледом. Није повезан са изворним сајтом и нема научне потврде. Ради ван мреже.","detail":"Атлас 1134 духовна курса/иницијације без интернета (списак са cursurispirituale.webnode.ro, није повезан), са историјским контекстом и критичким расуђивањем; без научне потврде.","tags":["духовност","атлас","критичко разликовање"]},"Profund":{"line":"150 питања која разговор воде даље од ћаскања — међу пријатељима или у породици. Играјте на екрану или одштампајте, са необавезним тајмером.","detail":"Игра од 150 питања за садржајне разговоре (RO/EN/FR), онлајн или одштампана, са играчима и опционалним тајмером; прилагођено са deepcards.org, оригинали остају својина носилаца права (MIT само за код и оригинални део).","tags":["разговор","картице","trade-free"]},"Universul-Observabil":{"line":"Колики је видљиви Свемир? Упоредите три мапе (линеарну, равну, у простору) и радите космолошке прорачуне. Бројеви нису независно проверени.","detail":"Почетна страница која представља и упоређује 1D, 2D и 3D визуелизације видљивог Универзума, са космолошким калкулатором без интернета; бројке и рекорди су из каталога из маја 2026, нису независно проверени. RO/EN.","tags":["астрономија","космологија","визуелизација"]},"Universul-Observabil-1D":{"line":"Путујте од нас до ивице видљивог Свемира поред 112 галаксија распоређених на једној оси. Иронични тон, заокружене вредности, образовна сврха.","detail":"1D мапа видљивог Универзума: 112 галаксија на радијалној оси (време, удаљеност, црвени помак), са табелом података и извозом у CSV. Образовно, иронијског тона; заокружене вредности, рекорди на дан каталога (мај 2026).","tags":["астрономија","космологија","визуелизација"]},"Universul-Observabil-2D":{"line":"Мапа галаксија у сатиричном издању «Равна Земља»: то је шала, Земља није равна. Зумирајте међу 111 галаксија; удаљености су приближне. Ради ван мреже.","detail":"Интерактивна 2D мапа видљивог универзума (111 галаксија, логаритамска скала, JWST подаци) у сатиричном издању „Равна Земља“: пародија, Земља није равна; удаљености су приближне. RO/EN, без интернета.","tags":["астрономија","сатира","космологија"]},"Universul-Observabil-3D":{"line":"Летите међу више од 115 галаксија на 3D мапи, са вођеним турама и мисијама. Вредности су приближне.","detail":"Интерактивна 3D мапа (WebGL) видљивог универзума: 115+ галаксија, 12 хоризоната, 30 тура, изазови у водичу, извоз у GLB/CSV/BibTeX. Приближне вредности; JWST рекорди на мај 2026.","tags":["астрономија","космологија","3D"]},"QSO":{"line":"Водите дневник радио-веза своје радио-аматерске станице са UTC временом, локаторима и статистиком. Незванично; прорачуни су приближни.","detail":"Незванични дневник радио-аматерске станице: QSO са UTC сатом, увоз/извоз ADIF 3.1, Maidenhead локатори, провере дупликата, статистика. Делимична табела префикса (није DXCC); приближни прорачуни.","tags":["радио","дневник"]},"Curatitor":{"line":"Погледајте шта откривају ваше фотографије и датотеке (место, камера, аутор) и уклоните те податке пре слања. Не сакрива лица нити други видљив садржај.","detail":"Локално приказује и уклања метаподатке датотека (GPS, камера, аутор, софтвер) без поновног кодирања пиксела или звука и поново проверава резултат. Не анонимизује садржај (лица, шум сензора).","tags":["метаподаци","приватност"]},"Poteca":{"line":"Отворите трагове снимљене на планинарењу или бициклу и видите даљину, успон и профил висине. Можете сећи или спајати. Нема мапе; успон је процењен.","detail":"Прегледач и уређивач GPX/GeoJSON/KML/CSV стаза: статистика, висински профил, сечење, спајање, упрошћавање, извоз. Без подлоге мапе; успон/спуст су процене.","tags":["GPX","трагови"]},"Orar":{"line":"Календар и недељни планер са званичним румунским празницима, са приказом по дану, недељи или месецу. Аларми звоне само док је страница отворена.","detail":"Календар и недељни планер: прикази месец/недеља/дан/агенда, понављања по RFC 5545, временске зоне, румунски државни празници, увоз/извоз .ics. Аларми звоне само док је картица отворена.","tags":["календар","време"]},"Alfabete":{"line":"Учите и вежбајте Морзеову азбуку, Брајево писмо, фонетски алфабет, заставичну семафорску азбуку и старе шифре, па одштампајте страницу. Старе шифре не штите тајне.","detail":"Референца, конвертор, тренер и штампани лист за Морзеову азбуку, брајев запис (степен 1), фонетске азбуке, семафор, Бодо, бројевне основе и класичне шифре. Класичне шифре не нуде безбедност.","tags":["кодови","учење"]},"Fabrica":{"line":"Напишите курс као обичан текст и претворите га у страницу са лекцијама, завршним тестом и сертификатом за штампање. Сертификат нема званичну вредност.","detail":"Фабрика курсева и квизова: напишите курс у обичном Markdown-у и извезите га као једну самосталну HTML датотеку са локалним напретком, завршним тестом и штампаним сертификатом (без акредитационе вредности).","tags":["курсеви","израда"]},"Bolta":{"line":"Какво је било небо изнад главе на било ком месту и дану између 1900. и 2100? Сунце, Месец, планете и звезде, као и помрачење 2027. Вредности су израчунате, незванично. Ради ван мреже.","detail":"Планетаријум без интернета за било које место и време између 1900. и 2100.: Сунце, Месец, планете, 1.627 звезда, сазвежђа, догађаји и страница о помрачењу 2027. Израчунате вредности, незванично.","tags":["астрономија","планетаријум"]},"BRAZDA":{"line":"Декодирајте Војаџерову златну плочу корак по корак, па кодирајте нови диск за сонду која се лансира сада. Слике у првим корацима су шематске, нису NASA-ине.","detail":"Декодер и кодер у 12 корака за Voyager Golden Record: брзина, водонични сат, мапа пулсара, сигнал слике, калибрација помоћу круга, декодирање линију по линију, боја, ваша сопствена датотека, прилози и кодирање диска 2026–2027.","tags":["Војаџер","сигнал"]},"Arbore":{"line":"Направите породично стабло са особама, породицама, временском линијом и румунским калкулатором сродства. Подаци остају само у овом прегледачу, нема синхронизације.","detail":"Локална генеалогија: особе, породице, увоз/извоз GEDCOM 5.5.1, SVG дијаграми, временска линија, калкулатор сродства (само румунска терминологија). Без синхронизације; подаци остају у овом прегледачу.","tags":["родослов","GEDCOM"]},"Gospodar":{"line":"Пратите кућни новац: рачуне, трошкове, месечне буџете и извештаје. Налог није потребан, али ако изгубите лозинку, губите податке. Није финансијски савет.","detail":"Локални кућни буџет: рачуни, категорије, трансакције, увоз CSV, месечни буџети, извештаји и калкулатори са транспарентним формулама. Без налога или синхронизације; изгубљена лозинка значи изгубљене податке. Није финансијски савет.","tags":["буџет","лични финансије"]},"Decibel":{"line":"Измерите колико је гласна бука око вас и погледајте од којих се звукова састоји. Постоји и оријентациони тест слуха. Није сертификован уређај; резултати зависе од микрофона.","detail":"Мерач нивоа звука, анализатор спектра (1/3 октаве, FFT) и оријентациони тест слуха. Није сертификован мерач и нема правну или медицинску вредност; очитавања зависе од микрофона и калибрације.","tags":["звук","мерење"]},"Provenienta":{"line":"Имате слику и желите да знате ко ју је потписао и које измене је пријавио? Проверите уграђени дигитални потпис. Експериментално, тестирано само на примерима датотека.","detail":"Локални, експериментални проверавач C2PA / Content Credentials: показује ко је потписао и које су измене декларисане, и проверава потпис и везу са бајтовима датотеке. Тестирано само на синтетичким датотекама; нема листе поверења.","tags":["C2PA","порекло"]},"Lexicon":{"line":"Донесите своје речнике и тражите речи чак и ако пишете без дијакритика или са грешкама. Долази само са малим демонстрационим скупом. Ради ван мреже.","detail":"Мотор речника без интернета: донесите сопствене речнике (TSV/CSV, JSON, StarDict, dictd, XDXF) и претражујте по префиксу, без обзира на акценте, приближно или у пуном тексту. Приложени скуп (345 ставки) је демо, не комплетан речник.","tags":["речник","језик"]},"VERIGA":{"line":"Проналази покварене везе и осиротеле датотеке на сајту или у фасцикли. Ради на Windows-у, macOS-у и Linux-у; потребно је мало познавање рачунара.","detail":"Проверавач веза (clean-room) за веб-сајтове и локалне фасцикле, писан у Rust-у: командна линија, изворна десктоп апликација (egui) и верзија у једној HTML датотеци. Проверава HTML и CSS везе, преусмеравања, #fragment сидра, датотеке сирочад, robots.txt и sitemap. Windows, macOS и Linux; MIT лиценца.","tags":["провера веза","MIT"]},"TEZAUR":{"line":"Асистент за тезу који пише само на основу ваших књига и чланака, са проверљивим цитатима. Ради на вашем рачунару; ваши документи га никада не напуштају. У развоју.","detail":"Локални истраживачки асистент за писање тезе, писан у Rust-у, са одговорима утемељеним на цитатима: индексира ваше књиге и чланке (PDF, EPUB, DOCX, txt), проналази одломке и пише искључиво на основу њих, са проверавеним цитатима [n] и списком литературе. Ради на вашем рачунару са локалним моделом (Ollama, Jan, LM Studio); ваши документи га никада не напуштају. Верзија 0.x; MIT лиценца.","tags":["истраживање","MIT"]},"LegatorOCR":{"line":"Скенирајте књигу и добијте чист PDF са исправљеним страницама и текстом који се може претраживати. Ради на Windows-у, macOS-у и Linux-у; ваши скенови остају код вас.","detail":"Clean-room накнадни процесор писан у Rust-у за скениране књиге: дели двостране развијене странице, исправља нагиб, опсеца, поставља маргине, чисти и бинаризује, па извози PDF или слике са OCR текстуалним слојем који се може претраживати. Графичка апликација (Windows, macOS, Linux) и командна линија, на 8 језика. Препознавање текста (OCR) захтева посебан програм Tesseract; све остало ради без њега. Верзија 0.x; MIT лиценца.","tags":["скенирање","MIT"]},"Fenarium":{"line":"Атлас и радионица субјективних перцепција кроз сва чула, почев од фосфенизма: курс од 13 модула, вођени експерименти, визуелни симулатор и лабораторија А/Б самоексперимената са рандомизацијом. Образовно, није медицински уређај.","detail":"Атлас фена (фосфени, накнадне слике, звуци налик тинитусу и још), курс од 13 модула, лабораторија за самоексперименте; није медицински уређај.","tags":["перцепција","MIT"]},"MENSURA":{"line":"Измерите IQ, EQ, CQ, RQ, извршне функције и чула у 6 области помоћу 18 тестова, композитних индекса и 95% интервала поверења. Привремене норме, само оријентационо, није дијагноза.","detail":"18 тестова у 6 области (IQ, EQ, CQ, RQ, извршне функције, чула), индекси са интервалима поверења, извоз/увоз у JSON; привремене норме.","tags":["тестови","MIT"]},"Cronosala":{"line":"Тајмери за теретану: одмор између серија, HIIT, Табата, EMOM, AMRAP, кругови и метроном, плус дневник тренинга са кг и понављањима.","detail":"Тајмери за теретану и дневник тренинга у једној HTML датотеци: прилагодљив одмор између серија, Interval/HIIT, Tabata, EMOM, AMRAP, кружни тренинг по станицама, темпо, метроном, месечни програм од 4 недеље, каталог вежби и QR кодови за справе. Подаци остају у прегледачу; интерфејс је на румунском.","tags":["спорт","време"]},"ScutSonor":{"line":"Гласан звук и стробоскоп лампе за сусрете са агресивним псима, плус водич за понашање. То је помоћ, а не загарантован штит.","detail":"Генерише пролаз 2–8 kHz, експериментални ултразвук, сирену и тест звучника, са лимитером који чува јачину звука, стробоскоп лампом (2,5 Hz), дневни режим и безбедносни водич. Једна датотека, без праћења. Докази да звук одвраћа псе су слаби.","tags":["безбедност","звук"]},"MIRAJ":{"line":"Како види мрежњача и како мозак гради слику: фовеа, слепа мрља, илузије и квиз, на три нивоа.","detail":"Интерактивно објашњење вида на три нивоа (почетни, средњи, напредни): мрежњача, фовеа, слепа мрља, оптичке илузије, резиме и квиз од 10 питања. Једна датотека, интерфејс на румунском и енглеском.","tags":["вид","образовање"]},"ANTROPOS":{"line":"Оријентациони научни профил који се рачуна локално: биолошка старост PhenoAge, глас, рукопис, цртање сата, TIPI личност и време реакције.","detail":"Образовни алат за скрининг, није дијагноза: биолошка старост PhenoAge са заштитом од неуверљивих вредности, анализа гласа, графометрија рукописа, тестови сата и цртања особе, TIPI, тестови реакције, штампани извештај и извоз у JSON. Подаци остају у прегледачу.","tags":["скрининг","биологија"]},"DESCANTAR":{"line":"Бацање пасуља са 41 зрном (метода 3×3, олтенска варијанта) и 12 традиционалних бајања као предмет фолклорног проучавања.","detail":"Румунско гатање на пасуљ у три методе (3×3 по књизи, Олтенија, три гомиле), читања по Глави, Срцу и Стопалима, 12 традиционалних басми, фаза Месеца, бројач рецитовања, генератор басми, историја и водич који се може копирати. Фолклорни садржај преведен на 8 језика уз помоћ AI-ја, без прегледа изворних говорника.","tags":["фолклор","пасуљ"]},"Index-fara-frontiere":{"line":"Каталог једнофајлних HTML апликација: колекција chiuta.github.io и спољни извори, са претрагом и ознакама.","detail":"Осам пројеката из ауторове колекције и осам спољних ресурса, јасно означених, са претрагом уживо, ознакама на које се може кликнути, RO/EN прекидачем, тамном/светлом темом и ставком која каталогизује саму себе. Без мрежних захтева. Статички снимак од 5. јула 2026.","tags":["каталог","извори"]},"DECUPAJ":{"line":"Претворите подкаст, аудио или видео у вертикалне клипове са титловима директно у прегледачу, без налога и воденог жига. Ваше датотеке никада не напуштају уређај.","detail":"Вертикални рилови из подкаста (аудио или видео) у једној HTML датотеци: изаберите одломак на таласном облику, добијте предлоге тренутака, локална транскрипција помоћу Whisper-а, стилизовани титлови, 4 размере (9:16, 4:5, 1:1, 16:9), ред за извоз и MP4 преко WebCodecs-а. Интерфејс на 8 језика.","tags":["reels","видео"]},"LECTOR":{"line":"Књиге читане наглас директно у прегледачу: EPUB, DOCX, PDF, TXT или налепљен текст, без налога и сервера. Текст никада не напушта ваш уређај.","detail":"Слушајте књиге прочитане наглас из једне HTML датотеке: EPUB, DOCX, PDF (са румунским OCR-ом за скенове), TXT; гласови уређаја или Piper ro_RO, изговорена реч истакнута, тајмер за спавање, поглавља, обележивачи, речник изговора, локална библиотека и теме прилагођене дислексији. Интерфејс на 8 језика.","tags":["аудио","књиге"]},"FARFURIA":{"line":"Бесплатан дигитални нутрициониста: персонализоване калорије и макронутријенти, план оброка за 7 дана, дневник исхране и праћење тежине. Не замењује лекара ни нутриционисту.","detail":"Дигитални нутрициониста у једној HTML датотеци: циљеви калорија и макронутријената (Mifflin–St Jeor, ниво активности, циљ), 7-дневни план оброка са филтерима за дијету и алергене, база намирница, дневник исхране и праћење тежине. Безбедносна правила за малолетнике, историју поремећаја у исхрани и болест бубрега. Интерфејс на 8 језика.","tags":["исхрана","здравље"]},"VITALIS":{"line":"Лични пратилац за здравље, дуговечност и биохакинг: девет стубова рангираних по доказима, калкулатори, оцена начина живота и дневни ритуал. Није медицински савет.","detail":"Пратилац за здравље и дуговечност у једној HTML датотеци: девет стубова рангираних по доказима, калкулатори (HOMA-IR, TyG, однос струка и висине, Mifflin–St Jeor, зоне пулса, циклуси спавања, протеини), тајмер за пост, водич за дисање, 360 скор са радар дијаграмом, референтни опсези биомаркера и праћење дневног ритуала. Незванични пратилац догађаја BioHacking360. Интерфејс на 8 језика.","tags":["здравље","дуговечност"]},"REZONANTA":{"line":"Водич и алати за комуникацију и медије: порука, канали, саопштење за јавност, интервју, јасноћа, план и криза.","detail":"Како учинити да вас људи слушају, у једној HTML датотеци: 12 принципа са практичним тестом, „кућа поруке“ (30-секундни наступ, објава, кратка и изговорена верзија), препоруке за медијске канале, генератор саопштења за штампу по обрнутој пирамиди, лист за интервју, анализатор јасноће текста, план комуникације са извозом у текст/CSV и кораци првог сата кризе. Интерфејс на 8 језика.","tags":["комуникација","медији"]},"Claritas":{"line":"Свеобухватно проширење прегледача за приступачност: корекција контраста, режим читања, читање наглас и WCAG провера. Без телеметрије, без мреже, без налога.","detail":"Бесплатно проширење за приступачност у прегледачу: аутоматска исправка контраста (WCAG AA/AAA), теме високог контраста, филтери за далтонизам, већи текст и фонтови прилагођени дислексији, линија, маска и лупа за читање, режим читача, читање наглас, велике површине за клик и скенирање једним прекидачем, WCAG 2.2 ревизија, локални снимци екрана и снимање екрана. За Chromium, Firefox и Safari; интерфејс на 8 језика.","tags":["приступачност","проширење"]},"TurboCursa":{"line":"Псеудо-3D аркадна тркачка игра написана у Rust-у: пејзажи створени из семена, 11 режима, лигашка каријера и 2 играча. Оригинална; нема кода ни ресурса из друге игре.","detail":"Clean-room псеудо-3D аркадна тркачка игра писана у Rust-у: оригинални мотор, графика, музика и име, све генерисано из семена (19 пејзажа), кампања, вожња на време, бесконачни режим, Rush Hour, слалом, огледало, Blackout, Zen, против CPU-а, подељени екран за два играча и каријера по дивизијама. Ради изворно или као веб датотека; интерфејс на 8 језика.","tags":["трке","Rust"]},"ANTENA":{"line":"У изради: решавач жичаних антена компатибилан са NEC-2 (метода момената), са интерфејсом у прегледачу. За сада само пре-алфа скелет.","detail":"Рад у току: решавач жичаних антена компатибилан са NEC-2 (метод момената) са веб интерфејсом. За сада само прето-алфа скелет.","tags":["радио","антене"]},"ARBITRU":{"line":"У изради: универзални мотор правила за игре на табли, са картама, коцкама и загонетке, са декларативним језиком правила. За сада само пре-алфа скелет.","detail":"Рад у току: универзални мотор правила за друштвене игре, игре картама, коцкицама и слагалице, са декларативним језиком правила. За сада само прето-алфа скелет.","tags":["игре","правила"]},"ASTROLABIU":{"line":"У изради: мотор небеских догађаја у чистом Rust-у (временске скале, помрачења, излазак и залазак, календари). За сада само пре-алфа скелет.","detail":"Рад у току: мотор небеских догађаја (временске скале, помрачења, излазак и залазак, календари), у чистом Rust-у. За сада само прето-алфа скелет.","tags":["астрономија","календари"]},"ECOGRAMA":{"line":"У изради: уређивач спектрограма и рестаурација звука: бирајте на спектрограму, поправљајте, извозите. За сада само пре-алфа скелет.","detail":"Рад у току: уређивач спектрограма и рестаурација звука: изаберите на спектрограму, поправите, извезите. За сада само прето-алфа скелет.","tags":["аудио","рестаурација"]},"ecou-spectral-rs":{"line":"У изради: изворни Rust уређивач спектрограма са прикључцима за смањење шума и откривање звукова. Постоје оквир кода и формат прикључака, али још нема готових функција.","detail":"Рад у току: изворни Rust уређивач спектрограма са додацима за смањење шума и детекцију гласа. Има скелет кода и формат додатака, али још ниједну завршену функцију.","tags":["аудио","Rust"]},"MARTOR":{"line":"У изради: судско хватање веба у WARC/WACZ са хешевима, потписима и поузданим временским печатима, проверљиво ван мреже. За сада само пре-алфа скелет.","detail":"Рад у току: форензичко хватање веба у WARC/WACZ са хешевима, потписима и поузданим временским ознакама, проверљиво без интернета. За сада само прето-алфа скелет.","tags":["архивирање","докази"]},"NEAMURI":{"line":"У изради: мотор сродства — од путање у породичном стаблу до исправног термина сродства на многим језицима. За сада само пре-алфа скелет.","detail":"Рад у току: мотор сродства, од путање у породичном стаблу до исправног појма за рођака на многим језицима. За сада само прето-алфа скелет.","tags":["сродство","родослов"]},"TACTIL":{"line":"У изради: слој тактилног излаза: Брајеви формати (BRF, Unicode), дисплеји, штампачи у рељефу и вибрација екрана на додир. За сада само пре-алфа скелет.","detail":"Рад у току: слој тактилног излаза: брајеви формати (BRF, Unicode), дисплеји, штампачи и вибрација на екрану осетљивом на додир. За сада само прето-алфа скелет.","tags":["Брајево писмо","приступачност"]},"atelier-verificare":{"line":"Проверавајте фотографије, видео, везе и домене у прегледачу, ништа се не отпрема: прави тип датотеке и SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (само за читање), анализа нивоа грешке. Не може доказати да је фотографија права. Алфа.","detail":"Алатка за проверу за новинаре и пажљиве читаоце која ради локално. Додајте слике, видео-снимке, везе, домене или текст и добијте налазе са нивоом забринутости за сваки: прави тип датотеке, SHA-256, EXIF и GPS положај, XMP и IPTC, трагове AI генератора слика, манифесте Content Credentials (C2PA; читају се, не валидирају), анализу нивоа грешке за JPEG, метаподатке видеа са кључним сличицама за обрнуту претрагу слика и анатомију везе. Две опционалне мрежне провере (резиме DNS-а, Internet Archive) покрећу се тек пошто означите поље за сагласност. Извештај (Markdown, JSON или PDF) наводи ограничења методе. Не може доказати да је фотографија аутентична: непостојећи метаподаци говоре мало, а метаподаци се могу фалсификовати. Алфа; девет од једанаест провера ради без интернета; датотеке остају у прегледачу.","tags":["новинарство","провера","фотографије"]},"balanta":{"line":"Слепо упоређујте ВИ моделе: налепите одговоре два до осам модела на 92 упита на румунском, енглеском и мађарском, гласајте за A или B и добијте рангирање са интервалима. Алфа; ради ван мреже.","detail":"Слепо поређење AI модела једног поред другог на румунском. Одговоре сваког модела налепљујете сами (ништа се не позива: без API кључева, без налога), апликација сакрива имена модела унутар одговора, утврђује редослед на основу семена и бележи ваш глас. Рангирање користи Bradley–Terry и Elo са 95% bootstrap интервалима, плус стопу победа, пристрасност положаја и табеле директних дуела. Гласови и одговори су отворене JSON Lines датотеке. Са мало гласова или упутстава рангирање не говори ништа опште. Алфа; подаци остају у прегледачу; без праћења.","tags":["ВИ","евалуација"]},"calendarium":{"line":"Унесите датум у једном од једанаест календара (грегоријански, јулијански, јеврејски, хиџрански, персијски, кинески, маја, марсовски…) и видите га у свим осталим, са приказом месеца. Алфа; ради ван мреже.","detail":"Претвара датуме између једанаест календара (грегоријански, јулијански, ревидирани јулијански, хебрејски, хиџра, персијски, коптски, етиопски, кинески, мајански и Mars Sol Date), приказује јулијански дан, дан у недељи и ISO недељу, и има месечни приказ са другим календаром испод сваког дана. Укључује румунске напомене (стари и нови стил, прелазак 1919, Ускрс) и атлас календара, један додатак по календару. Вредности се израчунавају, уз наведена ограничења (хиџра је табеларни календар; опсези су заштићени). Алфа, на 8 језика, ради без интернета; без праћења.","tags":["календари","време"]},"glosar":{"line":"Речник ван мреже за влашки, мегленорумунски и романи: тражите без дијакритика, видите које основне речи недостају и додајте речи са извором и регистром. Алфа.","detail":"Речници мањинских и угрожених језика, које праве њихови говорници. Претражује без обзира на дијакритике, приказује поузданост (нацрт, са извором, прегледано), има табелу покривености 50 основних појмова и омогућава додавање речи са извором, лиценцом и снимком (до 50 KB). Извози TSV и Anki датотеке и датотеку прилога за пројекат. Почетне листе су мале — бројеви и неколико речи, свака са објављеним извором — и ниједан говорник их још није прегледао. Алфа; ради без интернета; подаци остају у прегледачу док их не преузмете.","tags":["језици","речници"]},"graiul":{"line":"Архива румунског фолклора ван мреже (пословице, бајања, загонетке, коледе) са извором, округом и сагласношћу. Почиње са десет пословица; можете додати још. Алфа.","detail":"Претрага без обзира на дијакритике, са филтерима по типу, округу и поузданости; пословица дана (иста за све на одређени датум), схематска плочаста мапа 41 округа и Букурешта, и образац за додавање који захтева извор и, за басме и све што је прикупљено од особе, сагласност. Извози датотеку прилога и TSV. Почетни подаци су десет румунских пословица са Wikiquote-а; ниједну није прегледао фолклорист. Алфа; ради без интернета; подаци остају у прегледачу док их не преузмете.","tags":["фолклор","архива"]},"indicativ-international":{"line":"Вежбајте питања за радио-аматерски испит уз распоред понављања са пет кутија и пробне испите на време; увезите пакете питања у заједничком JSON формату. Укључено 50 вежбовних питања; није званична банка. Алфа.","detail":"Тренер и симулатор испита за питања за радио-аматерске дозволе, са заједничким форматом пакета како би свака земља могла да дода своју банку. „Вежбање“ понавља тачне одговоре након 1, 3, 7, 14 и 30 дана и објашњава сваки одговор са његовим извором; „Испит“ је тест на време са прагом пролаза; „Пакети“ увози и проверава пакете и прави резервну копију вашег напретка. Уграђени пакет садржи 50 оригиналних вежбовних питања написаних за овај пројекат — није званична банка — и још није укључен ниједан пакет земље. Алфа; ради без интернета; напредак остаје у прегледачу.","tags":["радио","испити"]},"proiector-fara-frontiere":{"line":"Телефони у учионици постају заједнички екран без сервера и налога: тајмер, анкета, квиз, белешке и табла; упаривање QR кодом или налепљеним текстом на истој мрежи. Алфа: на правим телефонима још није тестирано.","detail":"Заједнички екран за учионицу, без сервера и без налога. Наставник отвара страницу на пројектору; телефон сваког ученика се придружује разменом кода (QR оквири, фотографија кода или налепљени текст), до 30 телефона истовремено. Укључено је пет активности: одбројавање, анкета са тракама уживо, квиз (питања из JSON, обичног текста или CSV датотеке; тачан одговор остаје на пројектору док се не открије; бонус за брзину и табела резултата), лепљиве белешке и табла са једном бојом по телефону. Резултати се могу сачувати као CSV, текст или PNG. Свака активност ради у изолованом оквиру само са дозволама које декларише, а нова активност је један дескриптор и једна скрипта. Наставник може закључати или уклонити телефон и окончати сесију; сваки уређај бира свој језик (осам) и изглед (тамни, високи контраст, велики текст). Ради без интернета када се једном отвори и може се инсталирати. Алфа: тестирано у Chromium-у са стварним везама на једној машини, не на стварним телефонима, другим прегледачима или школским мрежама. Упаривање захтева исту локалну мрежу (без релеја), приказује IP адресу сваког уређаја другом и не проверава ко је други уређај. Формат квиза „Undava“ није подржан: није пронађена спецификација.","tags":["учионица","пројекција","квиз"]},"regula":{"line":"Играјте пет класичних игара за двоје (мица, алкерк, фанорона, му тореере, хнефатафл) против рачунара или пријатеља; додајте своју игру као JSON. Алфа; ради ван мреже.","detail":"Један мотор правила за традиционалне друштвене игре: свака игра је JSON датотека, а текст правила на осам језика генерише се из истих података које мотор игра, тако да се текст и игра не могу разилазити. Свака страна може бити особа, насумични играч или рачунар на два нивоа; поништи, понови, савет и запис потеза који можете копирати. Можете налепити, потврдити и играти сопствену игру. Игре су реконструкције, не турнирска правила, а свака наводи колико је сигурна у своја правила. Алфа; ради без интернета; без праћења.","tags":["игре","правила"]},"vietar-packs":{"line":"Прегледајте, увезите, проверите и направите регионалне пакете врста за VietAR: имена на неколико језика, ознаке токсичности, сличне врсте. Пет нацрта почетних пакета са 71 врстом. Алфа; ради ван мреже.","detail":"Регионални пакети врста за VietAR: имена на неколико језика, ознака токсичности, опасни сличници и место за лиценциране фотографије и везе до звукова. Прегледајте и претражујте пет почетних пакета (Румунија: биљке и гљиве, птице, сисари; Бугарска и Молдавија: скелети), увезите пакет, проверите га истим правилима као репозиторијум или направите један за школско одељење или клуб природњака. Почетни пакети су нацрти без фотографија и звукова, а „није означено као токсично“ никада не значи јестиво или безбедно. Апликација VietAR још не може да увози пакете. Алфа; ради без интернета.","tags":["природа","врсте"]},"PatruZeci":{"line":"Илустровани анимирани атлас употреба WD-40: водич од 147 картица и званична листа од 1993 употребе, свака са својом анимираном сценом. Незванично, ван мреже, без налога.","detail":"Илустровани, анимирани атлас употреба спреја WD-40 у једној датотеци без интернета: водич од 147 картица у 14 категорија (са нивоом ризика и оним што спреј ради), званична листа „2000+ употреба“ са 1993 ставке и одељак од 25 додатних употреба, митова и упозорења из веб чланака. 131 анимирана варијанта сцена, филтери по категорији и функцији, интерфејс на 8 језика. Незванична, независна апликација.","tags":["WD-40","уради сам"]},"ODISEEA":{"line":"Документарни филм од око 4,5 минута о Војаџерима 1 и 2 у једној HTML датотеци: сцене се стварају на графичкој картици, извоз у 2D и 3D за VR наочаре, на 8 језика.","detail":"Документарац од око 4,5 минута о сондама Voyager 1 и 2, у једној HTML датотеци која ради локално у прегледачу, без сервера и инсталације. Процедуралне сцене које генерише графичка картица (WebGL): планете, сонда, ракета, DSN антена, Golden Record, хелиосфера, Pale Blue Dot. Јавне слике NASA/JPL и Wikimedia Commons, или ваша слика за сваку сцену. Извоз у 2D, половичном (1920×1080) и пуном (3840×1080) 3D side-by-side формату, и режим за телефон за VR наочаре као што је VR BOX; амбијентална музика генерисана у прегледачу, опциона нарација. Интерфејс, нарација, титлови и шпица на 8 језика.","tags":["Војаџер","документарац"]},"EXIF-CURAT":{"line":"У изради: алат у Rust-у са меморијски безбедним парсерима за преглед и чишћење скривених података у датотекама (слике, PDF, Office, видео: EXIF, GPS, XMP). За сада само пре-алфа скелет.","detail":"Рад у току: алатка за преглед и уклањање скривених података у датотекама (слике, PDF, Office, видео: EXIF, GPS, XMP), са парсерима безбедним по меморију, писана у Rust-у. За сада само прето-алфа скелет.","tags":["метаподаци","приватност"]},"PORUMBEL":{"line":"Аутоматски преноси фотографије снимљене на телефону у Open Camera у фасциклу на рачунару, једна фасцикла по сесији, и отвара их у LegatorOCR-у. Без налога, без облака, без crate-ова трећих страна.","detail":"Мали програм писан у Rust-у, без крејтова трећих страна (Windows, macOS, Linux), који пребацује фотографије снимљене помоћу Open Camera на ваш рачунар: преко Wi-Fi-ја (страница за отпремање или WebDAV, са QR кодом), преко ADB-а (USB или Wi-Fi) или из синхронизоване фасцикле (Syncthing итд.). Разврстава фотографије у једну фасциклу по сесији снимања и отвара сваку завршену сесију у LegatorOCR-у (подела, исправљање нагиба, опсецање, PDF са OCR-ом). Локални контролни панел и команда „porumbel doctor“ за дијагностику; ништа не напушта вашу мрежу. Верзија 0.x; MIT лиценца.","tags":["фотографије","пренос"]},"colibri-companion":{"line":"Пријатељска десктоп апликација за локални мотор закључивања colibri: изаберите модел који одговара вашем рачунару, преузмите једним кликом и ћаскајте с њим. Без налога, без облачног сервиса.","detail":"Десктоп апликација писана у Rust-у за colibri (JustVugg/colibri): проналази Python и colibri, приказује само моделе који стају у меморију вашег рачунара, преузима их уз паузу и наставак, покреће локални сервер и отвара ћаскање (одговори у току, Markdown, сачуване конверзације, претрага, локални документи и MCP алати са одобрењем при сваком позиву). Панел Ресурси приказује процесор, меморију, графичку картицу и отворене везе. Windows, macOS, Linux; интерфејс на 8 језика; лиценца Apache-2.0.","tags":["локална ВИ","десктоп"]},"CartaColibri":{"line":"Локална ВИ библиотека на мотору Colibrì: индексира фасцикле које изаберете, тренутно претражује и тражи од локалног модела да сажме, извуче податке или синтетизује, увек наводећи изворну датотеку. Ништа не напушта ваш рачунар.","detail":"Програм писан у Rust-у, са локалном страницом (127.0.0.1) и командном линијом. Индексира фасцикле које изаберете (оригинали се само читају, никада не мењају), претражује пун текст (речи, „фразе“, префикс*, AND/OR/NOT, филтери по типу, величини, локацији) и групише датотеке. Локални модел Colibrì сажима, издваја (табела или JSON, „NOT FOUND“ уместо нагађања), синтетише или упоређује, увек уз цитиране изворе [S1], [S2] и оцену утемељености. Има и мали веб-прегледач за хватање, MCP сервер само за читање, увозе (обележиваче, Obsidian, Zotero, RSS) и проверу вашег текста у односу на библиотеку. Без налога, без телеметрије; интерфејс на 8 језика; алфа верзија 0.2; MIT лиценца.","tags":["локална ВИ","библиотека"]},"PolyTabletop":{"line":"240 друштвених игара против рачунара у терминалу или графичком прозору, плус игра у двоје на једној тастатури или преко мреже. Написано у Rust-у; мотор и игре немају спољне зависности.","detail":"Clean-room колекција друштвених игара писана у Rust-у: 240 игара које се могу играти против рачунара, у терминалу или у графичком прозору, плус игра за двоје на истом уређају и преко мреже. Апстрактни класици, игре картама и коцкицама, оригиналне варијанте савремених механика под сопственим именима, кооперативне игре са AI партнером, игре са скривеним улогама, друштвене игре и игре речима; каталог има 1200 ставки, са алаткама за игре улога (коцкице, листови, генератор тамница, симулатор битака). AI противник (alpha-beta, MCTS), арена AI против AI-ја, транскрипти и понављања. Интерфејс на 8 језика; верзија 0.9; MIT или Apache-2.0 лиценца.","tags":["друштвене игре","Rust"]},"STRAJA":{"line":"Штит од ВИ агената који читају ваш телефон: показује које апликације могу да читају ваша обавештења, екран, фотографије и SMS, упозорава када нова добије приступ и води вас до подешавања где опозивате дозволу. Без налога, без INTERNET дозволе.","detail":"Апликација за Android (APK) и iPhone (непотписани IPA). На Android-у наводи апликације са приступом обавештењима, сервисима приступачности, улогом асистента и дозволама за медије и SMS, са оценом ризика по апликацији и за цео телефон; периодични монитор упоређује телефон са основном линијом и обавештава вас о сваком новом приступу. Отвара тачну страницу системских подешавања за опозив приступа и никада тихо ништа не мења. Привремени приступ са подсетником и водич заштите од 12 ставки. На iPhone-у нема ревизије (iOS крије дозволе других апликација), само водич, ручни регистар и подсетници. Не може зауставити агента. Без INTERNET дозволе, без резервне копије; 8 језика; верзија 1.0; MIT лиценца.","tags":["приватност","телефон"]},"CUPLAJ":{"line":"Телефонија са заједничком линијом за имерзивно позориште: флота обичних Android телефона постаје приватна централа преко Wi-Fi-ја простора; без облака, без налога, без реклама. Препознатљива функција је «cuplaj»: заједничка линија фиксних телефона од 1980-их до око 2006.","detail":"Android апликација (APK) и апликација за iPhone/iPad (непотписани IPA). Организатори и глумци разговарају са гледаоцима преко локалног Wi-Fi-ја; један телефон (контрола) је централа. Шест телефонских ера (1985 бирчни, 1995 тастатура, 2003 мобилни, 2025 паметни телефон, 2045 носиви уређаји, 2080 заједнички ум), заједничка линија у којој два претплатника деле једну линију, прави позиви, јавно обраћање притиском за говор, позадински канал, знакови (текст преко целог екрана, вибрација, звоњава, блиц, изговорени глас, фантомски позив) и сценарио са GO и PLAY. Без инфраструктуре, опциони AES-128-GCM мрежни кључ, директни P2P позиви. Без аналитике, без сервера, без налога. 8 језика; верзија 1.10; MIT лиценца.","tags":["имерзивно позориште","телефонија"]},"LUSTRUM":{"line":"Вратите простор на телефону: проналази непотребне датотеке, дупликате, сличне фотографије и остатке апликација и чисти их само уз вашу сагласност. Нема INTERNET дозволу, па физички не може ништа никуда да пошаље.","detail":"Android апликација (Kotlin). Простор по типу датотеке, велике, старе и непотребне датотеке, тачни дупликати (величина, брзи отисак, па SHA-256), сличне фотографије (перцептуални хеш), остаци деинсталираних апликација, JPEG компресија, кеш меморије, мутне и мрачне фотографије, Swiper (лево = обриши, десно = задржи), заказано чишћење и LUSTRUM корпа од 30 дана за поништавање. Без INTERNET дозволе: ништа не напушта телефон. Без магије на нивоу root-а: Android 11+ држи сваку обичну апликацију ван фасцикли са подацима других апликација. 8 језика (машински преводи); бета верзија 0.8; MIT лиценца.","tags":["чистач телефона","Android"]},"STENOGRAMA":{"line":"Транскрипција дугог аудија директно у прегледачу помоћу локалног Whisper-а: једна HTML датотека, без налога, без сервера, без воденог жига. Ваш аудио никада не напушта уређај; преузима се само Whisper модел, једном.","detail":"Чита MP3 и WAV у деловима (па дужина није ограничена меморијом); остали формати (M4A, OGG/Opus, MP4, FLAC) се декодирају у целини. Сваки одсечак се сече на паузи да се речи не поделе; напредак се чува, па можете стати и наставити. Уређивач на страници (кликните на време да чујете место), уклањање типичних Whisper-ових фантомских фраза, извоз у .txt, .srt, .vtt, .docx или у клипборд. Користи WebGPU када је доступан, иначе процесор (WASM). PWA који се може инсталирати; модел остаје у кешу након првог преузимања. Библиотека се учитава са jsDelivr-а при првој транскрипцији, проверена помоћу SHA-384. Интерфејс на 7 језика; MIT лиценца.","tags":["транскрипција","аудио"]},"GERMEN":{"line":"Обучите мали језички модел од нуле у чистом Rust-у на обичном процесору: без Python-а, без CUDA-е, без налога, без приступа мрежи, без телеметрије. Један бинарни фајл, једна текстуална датотека, једна команда.","detail":"Rust програм (на Burn-у, са његовим чисто Rust CPU бекендом) који тренира мрежу у стилу GPT преко бајтова или преко BPE речника наученог из вашег сопственог текста, па генерише текст из истренираног модела. GERMEN Studio: локални прозор (127.0.0.1) са кривом губитка, брзином и узорцима текста, на 8 језика. Команде за мерење брзине вашег рачунара и за проверу и поправку датотека модела. То је радионица за учење и експериментисање, не фабрика четботова: модел од 1–25 милиона параметара учи облик текста, не знање о свету. Без GPU-а, без мешовите прецизности. Верзија 0.6; MIT лиценца.","tags":["локална ВИ","Rust"]},"CUANTOR":{"line":"Симулатор квантног рачунара за ваш десктоп, од 5 до 1000 кубита, са интерфејсом у стилу IBM Quantum Composer-а. Тачна математика, али не прави квантни хардвер.","detail":"Rust програм у четири дела (језгро, прозор, командна линија, IBM веза) за Windows, macOS и Linux. Табла за цртање као IBM-ов Composer: ставите обојене капије на линије (кубите) и гледајте како траке и сфера приказују резултат, док текстуални панел исто коло уживо исписује у OpenQASM-у и Qiskit-у. Три калкулатора: један који памти сваки број (до 28 кубита), један веома брз за једноставне капије (до 4096) и један за кола са мало грана. Мерење, ресет и if усред извршавања, ваше сопствене капије, симулирани шум, резултати који се могу поновити помоћу семена. Чита OpenQASM 2.0 и 3.0; коло можете отворити у IBM Composer-у или послати на прави IBM рачунар уз кључ вашег сопственог налога (није проверено на стварном IBM хардверу). Интерфејс на 8 језика; верзија 0.2.","tags":["квантни рачунар","симулатор"]},"ERATA":{"line":"Коректор у прегледачу који проверава правопис, граматику, интерпункцију и типографију директно на вашем рачунару: без налога, без сервера, без телеметрије. Најдубљи за румунски.","detail":"Проширење за Chromium и Firefox (Safari верзија није тестирана), писано од нуле, без кода, правила или података из LanguageTool-а или било ког другог проверавача. Ради у пољима textarea, input и contenteditable и исцртава подвлачења без измене странице. Препознаје језик по пасусу, враћа дијакритике (ro, fr, es, pt) само тамо где је исправка недвосмислена и има дубока румунска правила (запета испод ș/ț, „să/sa“, „într-un“, зарез испред „dar/însă“). Лични речник, прилагођена правила, прекидач по сајту, увоз Hunspell речника. Опционално преформулисање преко локалног модела (само localhost, подразумевано искључено). Интерфејс на 25 језика. Верзија 0.4; MIT лиценца.","tags":["коректор","проширење"]}});
